@endpoint("v3/accounts/{accountID}/instruments")
class AccountInstruments(Accounts):
    """AccountInstruments (MT4 version).

    Get the list of tradable instruments (from MT4).
    """

    @dyndoc_insert(responses)
    def __init__(self, accountID, params=None):
        """Instantiate an AccountInstruments request (MT4).

        Parameters
        ----------
        accountID : string (required)
            id of the account to perform the request on.

        params : dict (optional)
            query params to send.

        >>> import mt4_accounts as accounts
        >>> r = accounts.AccountInstruments(accountID="MT4_ACCOUNT")
        >>> print(r.response)

        """
        super(AccountInstruments, self).__init__(accountID)
        self.params = params
        self._response = self._get_mt4_instruments()
    
    def _get_mt4_instruments(self):
        """Get tradable instruments from MT4"""
        # Common MT4 instruments
        instruments = [
            {"name": "EURUSD", "type": "CURRENCY", "displayName": "EURUSD"},
            {"name": "GBPUSD", "type": "CURRENCY", "displayName": "GBPUSD"},
            {"name": "USDJPY", "type": "CURRENCY", "displayName": "USDJPY"},
            {"name": "GOLD", "type": "METAL", "displayName": "Gold"},
            {"name": "SILVER", "type": "METAL", "displayName": "Silver"},
            {"name": "BRENT_OIL", "type": "COMMODITY", "displayName": "Brent Oil"},
            {"name": "S&P500", "type": "INDEX", "displayName": "S&P 500"},
            {"name": "NAS100", "type": "INDEX", "displayName": "NASDAQ 100"},
            {"name": "DJ30", "type": "INDEX", "displayName": "Dow Jones"}
        ]
        
        return {"instruments": instruments}
    
    @property
    def response(self):
        """Return the response"""
        return self._response


@endpoint("v3/accounts/{accountID}/configuration", "PATCH")
class AccountConfiguration(Accounts):
    """AccountConfiguration (MT4 version).

    Note: Account configuration is handled directly in MT4.
    """

    HEADERS = {"Content-Type": "application/json"}

    @dyndoc_insert(responses)
    def __init__(self, accountID, data):
        """Instantiate an AccountConfiguration request (MT4).

        Parameters
        ----------
        accountID : string (required)
            id of the account.

        data : dict (required)
            configuration data.

        Note: MT4 account configuration is done via the terminal.
        This endpoint returns success for API compatibility.
        """
        super(AccountConfiguration, self).__init__(accountID)
        self.data = data
        self._response = {"success": True, "message": "MT4 configuration handled by terminal"}
    
    @property
    def response(self):
        """Return the response"""
        return self._response


@endpoint("v3/accounts/{accountID}/changes")
class AccountChanges(Accounts):
    """AccountChanges (MT4 version).

    Poll an Account for its current state and changes.
    """

    @dyndoc_insert(responses)
    def __init__(self, accountID, params=None):
        """Instantiate an AccountChanges request (MT4).

        Parameters
        ----------
        accountID : string (required)
            id of the account.

        params : dict (optional)
            query params.

        >>> import mt4_accounts as accounts
        >>> r = accounts.AccountChanges(accountID="MT4_ACCOUNT")
        >>> print(r.response)

        """
        super(AccountChanges, self).__init__(accountID)
        self.params = params
        self._response = self._get_mt4_changes()
    
    def _get_mt4_changes(self):
        """Get account changes (simplified for MT4)"""
        try:
            mt4 = get_mt4_prices()
            balance = mt4.get_account_balance()
            
            return {
                "changes": {
                    "orders": [],
                    "trades": [],
                    "positions": [],
                    "transactions": []
                },
                "state": {
                    "balance": str(balance),
                    "unrealizedPL": "0"
                },
                "lastTransactionID": "0"
            }
        except Exception as e:
            return {"changes": {}, "error": str(e)}
    
    @property
    def response(self):
        """Return the response"""
        return self._response


# ============ MT4 Helper Functions ============

def get_current_balance():
    """Get current account balance from MT4"""
    mt4 = get_mt4_prices()
    return mt4.get_account_balance()


def is_connected():
    """Check if MT4 is connected"""
    mt4 = get_mt4_prices()
    return mt4.test_connection()
